'use strict';
// Presentation and progression layer. The original season, tactics and combat engine remain intact.
const ART={frames:{},ready:false,promise:null};
const ATLAS_SPECIES=[['minotaur','golem','troll','wendigo','direwolf','manticore','griffin','kitsune','wyvern','harpy','phoenix','kirin','basilisk','treant','naga','unicorn'],['cerberus','nemean','yeti','zaratan','owlbear','hydra','chimera','gargoyle','nekomata','jackalope','cyclops','thunderbird','sphinx','pegasus','arachne','salamander']];
const PREFS={motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,effects:true,sfx:true};
try{Object.assign(PREFS,JSON.parse(localStorage.getItem('manitoria-presentation')||'{}'))}catch{}
document.body.classList.toggle('reduced-motion',!PREFS.motion);
const originalSpriteCss=spriteCss;
spriteCss=function(){
 ART.promise=Promise.allSettled(ATLAS_SPECIES.map((list,a)=>new Promise((resolve,reject)=>{
  const img=new Image();img.onload=()=>{try{Object.assign(ART.frames,extractPortraitFrames(img,list));resolve()}catch(e){reject(e)}};img.onerror=reject;img.src=`assets/beasts-${a?'b':'a'}.png`;
 }))).then(results=>{originalSpriteCss();const style=document.createElement('style');style.id='beast-art';style.textContent=Object.entries(ART.frames).map(([sp,c])=>`.spr-${sp}{background-image:url("${c.toDataURL()}")!important}`).join('\n');document.head.append(style);ART.ready=true;if(results.some(r=>r.status==='rejected'))console.warn('Some illustrated beasts could not load; using original animated models.');});
};
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('toast-visible'),3300)}
function gems(rank,max=3){return `<div class="rank-gems" aria-label="Rank ${rank} of ${max}">${Array.from({length:max},(_,i)=>`<i class="${i<rank?'on':''}"></i>`).join('')}</div>`}
function beastArt(sp,cls=''){return `<span class="spr spr-${sp} ${cls}" aria-hidden="true"></span>`}
const FACILITIES={academy:{n:'The Grand Academy',icon:'✧',d:'Expert keepers help every beast learn faster.',bonus:'+10% experience per rank',base:160},forge:{n:'The Runic Forge',icon:'◇',d:'Runes bind to fang, claw, and horn.',bonus:'+4% attack per rank',base:190},sanctum:{n:'The Moonwell',icon:'☽',d:'An ancient well fortifies the entire menagerie.',bonus:'+6% maximum health per rank',base:160}};
const PATHS={hunt:{n:'Path of the Hunt',icon:'✦',d:'+7% attack and +3% critical chance per rank.',m:{atk:.07,crit:.03}},bastion:{n:'Path of the Bastion',icon:'⬡',d:'+10% health and +7% defense per rank.',m:{hp:.1,def:.07}},arcana:{n:'Path of the Arcane',icon:'✧',d:'+10% ability power and 5% shorter cooldown per rank.',m:{ap:.1,cd:.05}}};
function facilityRank(k){return G?.facilities?.[k]||0}
function facilityCost(k){return FACILITIES[k].base*(facilityRank(k)+1)}
function masteryCost(b){return 75+75*(b.mastery?.rank||0)}
function masteryLevel(b){return 4+4*(b.mastery?.rank||0)}
const originalMods=mods;
mods=function(b){const m=originalMods(b),r=b.mastery?.rank||0,p=PATHS[b.mastery?.path];if(p)for(const [k,v] of Object.entries(p.m))m[k]=(m[k]||0)+v*r;
 if(b.clubId==='P'&&G){m.atk=(m.atk||0)+facilityRank('forge')*.04;m.hp=(m.hp||0)+facilityRank('sanctum')*.06;m.xp=(m.xp||0)+facilityRank('academy')*.1}
 const sigExtra=Math.max(0,(b.perks?.sig||0)-1);if(sigExtra){m.ap=(m.ap||0)+sigExtra*.12;m.cd=(m.cd||0)+sigExtra*.05}return m};
PERKS.sig.max=3;
const originalPerkDesc=perkDesc;
perkDesc=function(b,k){if(k==='sig'&&(b.perks?.sig||0)>0)return `${SIG[SPECIES[b.sp].ab][1]} Each further rank adds 12% ability power and 5% shorter cooldown.`;return originalPerkDesc(b,k)};
const PERK_GROUPS={off:['claws','reflex','keen','bleed','executioner','breaker','fangs','berserk','twin','mark','apex','blades'],def:['hide','scales','stamina','wind','unshake','thorns','hardened','ironwill','juggernaut','undying','colossus'],abl:['focus','recovery','opening','rally','echo','sig','surge','chrono']};
function perkFit(b,k){const group=Object.keys(PERK_GROUPS).find(g=>PERK_GROUPS[g].includes(k));const role=ROLE_LINE[roleOf(b)];return group===(role==='front'?'def':role==='back'?'abl':'off')}
rollOffer=function(b){b.perks=b.perks||{};const allowed=Object.keys(PERKS).filter(k=>(b.perks[k]||0)<PERKS[k].max&&!(k==='blades'&&SPECIES[b.sp].range>=60));if(!allowed.length){b.offer=null;b.rerolls=0;return}
 const weights=tierW(b),out=[],draw=pool=>{if(!pool.length)return;const k=wpick(pool,pool.map(k=>weights[PERKS[k].t-1]*(perkFit(b,k)?1.6:1)));out.push(k)};
 // One role-relevant choice and one Rare-or-better choice; the final slot stays wild.
 draw(allowed.filter(k=>perkFit(b,k)));draw(allowed.filter(k=>!out.includes(k)&&PERKS[k].t>=((b.picksTaken||0)%6===5?3:2)));
 while(out.length<Math.min(3,allowed.length))draw(allowed.filter(k=>!out.includes(k)));b.offer=out;b.rerolls=0;
};
const originalTakePerk=takePerk;
takePerk=function(b,k){if(!b.offer?.includes(k)||!PERKS[k]||(b.perks?.[k]||0)>=PERKS[k].max||!(b.rolls>0))return false;b.picksTaken=(b.picksTaken||0)+1;return originalTakePerk(b,k)};
function statPreview(b,k){const before=combatStats(b),copy={...b,perks:{...b.perks,[k]:(b.perks?.[k]||0)+1}},after=combatStats(copy);const f=[['hp','Health',0],['atk','Attack',1],['def','Guard',0],['ap','Spell',2],['cd','Cooldown',1],['crit','Crit',2],['as','Atk/s',2]];return f.filter(([k])=>Math.abs(after[k]-before[k])>.001).slice(0,3).map(([k,n,d])=>`<span>${n} ${before[k].toFixed(d)} → <b>${after[k].toFixed(d)}${k==='cd'?'s':''}</b></span>`).join('')}
function upgradeCard(b,k,btn=''){const P=PERKS[k],r=b.perks?.[k]||0,group=Object.keys(PERK_GROUPS).find(g=>PERK_GROUPS[g].includes(k));return `<div class="pcard" style="--pc:${PTIER[P.t].c}"><span class="ptier">${PTIER[P.t].n} · ${r?'Rank '+(btn?r+1:r):'New power'}</span><div class="perk-icon" aria-hidden="true">${k==='sig'?'♜':{off:'✦',def:'⬡',abl:'✧'}[group]||'◇'}</div><b>${esc(perkName(b,k))}</b><div class="dust" style="font-size:12px;flex:1">${esc(perkDesc(b,k))}</div>${perkFit(b,k)?`<div class="fit-tag">↗ Suits your ${esc(roleOf(b).toLowerCase())}</div>`:''}${btn?`<div class="stat-preview">${statPreview(b,k)}</div>`:gems(r,P.max)}${btn}</div>`}
perkCard=upgradeCard;
function masteryHtml(b,edit){const owned=b.mastery?.path,rank=b.mastery?.rank||0,need=masteryLevel(b),cost=masteryCost(b);return `<div style="margin-top:26px"><div class="row between"><h3>Choose their legend</h3><span class="lbl gold">Specializations</span></div><p class="note">Commit to one path. Ranks unlock at levels 4, 8, and 12. Each rank strengthens the same identity.</p><div class="path-grid">${Object.entries(PATHS).map(([key,p])=>`<div class="path-card ${owned===key?'active':''}"><span class="lbl gold">${p.icon} ${owned===key?'Chosen path':owned?'Other path':'Specialization'}</span><h3>${p.n}</h3>${gems(owned===key?rank:0)}<p>${p.d}</p>${edit&&(!owned||owned===key)?`<button class="btn ${owned===key?'pri':''} sm" data-act="mastery" data-id="${b.id}" data-k="${key}" ${rank>=3||b.lvl<need||G.gold<cost?'disabled':''}>${rank>=3?'Path mastered':b.lvl<need?'Unlocks at level '+need:(rank?'Deepen path':'Choose path')+' · '+cost+' gold'}</button>`:''}</div>`).join('')}</div></div>`}
upgradesHtml=function(b,edit){b.perks=b.perks||{};if(edit&&b.rolls>0&&!b.offer)rollOffer(b);const owned=Object.keys(b.perks).filter(k=>b.perks[k]&&PERKS[k]).sort((a,z)=>PERKS[z].t-PERKS[a].t);const cost=rerollCost(b);return `${edit&&b.offer?`<div class="row between"><h3>A new power awaits</h3><span class="lbl gold">${b.rolls} picks available</span></div><div class="pcards lvcards" style="margin-top:16px">${b.offer.map(k=>upgradeCard(b,k,`<button class="btn pri" data-act="perk" data-id="${b.id}" data-k="${k}">Choose ${esc(perkName(b,k))}</button>`)).join('')}</div><div class="row" style="margin-top:14px"><button class="btn sm" data-act="reroll" data-id="${b.id}" ${G.gold<cost?'disabled':''}>Reroll · ${cost} gold</button>${G.cons.dice?`<button class="btn sm" data-act="use" data-id="${b.id}" data-k="dice">Use Loaded Dice · ${G.cons.dice} left</button>`:''}<button class="btn sm" data-act="autoperk" data-id="${b.id}">Choose for me</button></div>`:'<p class="note">Every level brings a choice of three powers. Earn experience in every bout, win or lose.</p>'}${b.clubId==='P'?masteryHtml(b,edit):''}<div class="lbl" style="margin:28px 0 12px">Learned powers · ${owned.length}</div>${owned.length?`<div class="pcards">${owned.map(k=>upgradeCard(b,k)).join('')}</div>`:'<p class="empty">Their story is only beginning.</p>'}<p class="note">Drafts favor your role and always include a Rare or better power when available. Every sixth choice offers an Epic or better when available. Signature ranks II and III add ability power and cooldown reduction.</p>`};
function viewAcademy(){const beasts=G.clubs.P.roster.map(id=>G.beasts[id]);return `<div class="stack"><section class="bill"><div class="kicker">Build more than a team</div><h2 style="font-size:34px;margin:14px 0">The making of legends.</h2><p>Raise your club. Shape each beast. Every investment follows your menagerie through the seasons.</p></section><div class="facility-grid">${Object.entries(FACILITIES).map(([k,f])=>{const r=facilityRank(k),cost=facilityCost(k);return `<section class="panel facility"><div class="facility-icon" aria-hidden="true">${f.icon}</div><h3>${f.n}</h3>${gems(r)}<p>${f.d}<br><span class="gold">${f.bonus}</span></p><div class="row between"><span class="note">${r?`Rank ${r} / 3`:'Not yet built'}</span><button class="btn pri sm" data-act="facility" data-k="${k}" ${r>=3||G.gold<cost?'disabled':''}>${r>=3?'Fully upgraded':(r?'Upgrade':'Build')+' · '+cost+' gold'}</button></div></section>`}).join('')}</div><div class="section-heading"><h2>Your future champions</h2><span>Specializations unlock at levels 4 / 8 / 12</span></div><div class="ascend-list">${beasts.map(b=>`<section class="panel">${beastArt(b.sp)}<div><h3>${esc(b.name)}</h3><p>${SPECIES[b.sp].n} · Level ${b.lvl}<br>${b.mastery?PATHS[b.mastery.path].n+' · Rank '+b.mastery.rank:'An unwritten legend'}</p>${b.rolls?`<span class="gold">${b.rolls} powers to choose</span>`:''}</div><button class="btn sm" data-act="profile" data-id="${b.id}" data-pt="skills">Develop beast</button></section>`).join('')}</div></div>`}
ACT.facility=d=>{if(!G||UI.mode!=='hub'||!FACILITIES[d.k])return;const cost=facilityCost(d.k);if(facilityRank(d.k)>=3||G.gold<cost)return;G.gold-=cost;G.facilities=G.facilities||{};G.facilities[d.k]=facilityRank(d.k)+1;ledger(`Upgraded ${FACILITIES[d.k].n}`,-cost);save();render();toast(`${FACILITIES[d.k].n} reached rank ${G.facilities[d.k]}.`);if(typeof playCue==='function')playCue('upgrade')};
ACT.mastery=d=>{const b=G?.beasts[d.id];if(!b||b.clubId!=='P'||UI.mode==='battle'||!PATHS[d.k])return;const r=b.mastery?.rank||0,cost=masteryCost(b);if(r>=3||b.lvl<masteryLevel(b)||G.gold<cost||b.mastery&&b.mastery.path!==d.k)return;G.gold-=cost;b.mastery={path:d.k,rank:r+1};ledger(`${b.name}: ${PATHS[d.k].n}`,-cost);save();render();toast(`${b.name} walks ${PATHS[d.k].n.toLowerCase()} · rank ${r+1}.`);if(typeof playCue==='function')playCue('upgrade')};
const navIcons={club:'M3 11 12 3l9 8v10H3ZM9 21v-8h6v8',roster:'M8 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM1 22v-5a7 7 0 0 1 14 0v5M16 3a4 4 0 0 1 0 8m2 3a6 6 0 0 1 5 6',market:'M3 8h18l-2-5H5ZM4 8v13h16V8M9 21v-8h6v8',shop:'m5 20 12-12m-3-3 5 5M3 22l4-1-3-3ZM14 3l7 7',academy:'m2 8 10-6 10 6-10 6ZM6 11v7l6 4 6-4v-7',league:'M3 20h18M6 20V11h4v9m4 0V4h4v16',leaders:'M8 2h8v7a4 4 0 0 1-8 0ZM8 5H3v3a5 5 0 0 0 5 5m8-8h5v3a5 5 0 0 1-5 5m-4 0v7m-5 2h10',bestiary:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3ZM12 5v17',legacy:'M12 3a9 9 0 1 1-9 9M2 3v6h6m4-4v7l4 2'};
renderTabs=function(){const lock=['battle','result','draft','season','cupdone','levelup'].includes(UI.mode);const tabs=[['club','Club house'],['roster','Menagerie'],['academy','Academy'],['market','Beast market'],['shop','Armory'],['league','League'],['leaders','Leaders'],['bestiary','Bestiary'],['legacy','Legacy']];$('#tabs').innerHTML=lock?'':tabs.map(([k,n])=>`<button class="tab ${UI.mode==='hub'&&UI.tab===k?'on':''}" data-act="tab" data-k="${k}" ${UI.mode==='hub'&&UI.tab===k?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${navIcons[k]}"/></svg>${n}</button>`).join('')+(UI.mode==='prematch'?'<button class="tab on" data-act="toPrematch">Match preparation</button>':'')};
const originalRender=render;
render=function(){document.body.dataset.mode=UI.mode;if(UI.mode==='battle'&&BT){renderTop();renderTabs();renderModal();return}if(UI.mode==='hub'&&UI.tab==='academy'){renderTop();renderTabs();$('#view').innerHTML=viewAcademy();renderModal()}else originalRender();};
const originalBcard=bcard;
bcard=function(b,extra){const html=originalBcard(b,extra);return html.replace('<div class="bhead">',`<div class="card-art" style="--h:${SPECIES[b.sp].hue}"><span class="card-rank">LEVEL ${b.lvl}</span><span class="card-role">${SPECIES[b.sp].role}</span>${beastArt(b.sp)}</div><div class="bhead">`)};
const originalViewClub=viewClub;
viewClub=function(){const mine=G.clubs.P.roster.map(id=>G.beasts[id]);const st=standings(),pos=st.findIndex(r=>r.id==='P')+1;return `<div class="club-welcome"><div><span class="lbl gold">Your club. Their legend.</span><h2>Welcome to the menagerie.</h2><p>Great beasts are born. Champions are made here.</p></div><div class="club-status"><b>${ordinal(pos)}</b>${TIERS[G.tier].n}</div></div><div class="club-roster-strip">${mine.slice(0,8).map(b=>`<button class="mini-beast-card" data-act="profile" data-id="${b.id}">${beastArt(b.sp)}${b.rolls?`<span class="upgrade-badge">${b.rolls}</span>`:''}<b>${esc(b.name)}</b><small>${SPECIES[b.sp].n}</small></button>`).join('')}</div>${originalViewClub()}`};
viewIntro=function(){const I=UI.intro,mem=castMembers(),random={id:'random',n:'A Twist of Fate',d:'Trust the keepers. Discover an unexpected combination of eight mythical beasts.',m:I.cast==='random'?mem:(I.rand||(I.rand=randomCast()))},cast=CASTS.find(c=>c.id===I.cast)||random;const moods={storm:'CONTROL · BURST · ILLUSIONS',hunt:'SPEED · PRESSURE · PURSUIT',wall:'DEFENSE · SUSTAIN · CONTROL',tricks:'SUMMONS · CHAOS · DECEPTION',random:'UNPREDICTABLE · YOUR STORY'};return `<div class="intro stack"><section class="intro-hero"><div class="hero-copy"><div class="hero-eyebrow">A MYTHICAL BEAST CLUB MANAGER</div><h1>Raise beasts.<br>Forge <em>legends.</em></h1><p>From the forgotten Mud Pits to the Mythic Arena. Build your menagerie, shape your champions, and give the crowds a name to remember.</p><div class="row"><button class="btn pri" data-act="foundFocus">Found your club <span aria-hidden="true">↗</span></button>${G?`<button class="btn" data-act="introContinue">Continue your story</button>`:'<span class="note">Your dynasty begins below.</span>'}</div></div><div class="hero-foot"><span>32 MYTHICAL SPECIES · 4 DIVISIONS · ONE LEGACY</span><span class="hero-scroll">THE ARENA REMEMBERS</span></div></section><div class="ladder" aria-label="Four league divisions">${TIERS.map((t,i)=>`<span class="rung ${i===0?'start':''}"><span class="num">${['IV','III','II','I'][i]}</span>${t.n}${i===0?'<small>Your beginning</small>':''}</span>`).join('<span class="arrow" aria-hidden="true">⟶</span>')}</div><section id="founding"><div class="section-heading"><h2><span class="section-n">01</span> Give your club a name</h2><span>Every great story starts somewhere.</span></div>${identityDesigner(I)}</section><section><div class="section-heading"><h2><span class="section-n">02</span> Choose your founding cast</h2><span>A playstyle. A personality. A beginning.</span></div><div class="castgrid">${CASTS.concat(random).map(c=>`<button class="castcard ${I.cast===c.id?'on':''}" data-act="introCast" data-k="${c.id}" aria-pressed="${I.cast===c.id}"><div class="cast-art">${[c.m[0],c.m[2],c.m[1]].map(([sp])=>beastArt(sp)).join('')}</div>${I.cast===c.id?'<span class="chosen-dot" aria-hidden="true">✓</span>':''}<div class="cast-info"><span class="ctitle">${c.n}</span><p>${c.d}</p><span class="cast-style">${moods[c.id]||'A DISTINCTIVE WAY TO FIGHT'}</span></div></button>`).join('')}</div></section><section><div class="section-heading"><h2><span class="section-n">03</span> Meet your founders</h2><span>${esc(cast.n)} · Eight beasts. Infinite possibilities.</span></div><div class="panel"><div class="founder-grid">${mem.map(([sp,t],i)=>`<div class="founder-item">${beastArt(sp)}<div><b>${SPECIES[sp].n}</b><small>${SPECIES[sp].role}${i===7?' · Whelp':''}</small><div class="ability-name">${ABINFO[SPECIES[sp].ab][0]}</div></div></div>`).join('')}</div>${I.cast==='random'?'<button class="btn sm" data-act="introRoll" style="margin-top:16px">Draw another cast</button>':''}<div class="intro-start"><p>Recruit, train, equip, and set each beast’s tactics. Fight 14 league matchdays and three cups per season. Your progress saves automatically.${G?' Founding a new club replaces your current club.':''}</p><button class="btn pri" data-act="introStart">Open the gates <span aria-hidden="true">→</span></button></div></div></section><div class="intro-footer">YOUR CLUB. YOUR CHAMPIONS. YOUR LEGACY.</div></div>`};
ACT.foundFocus=()=>{document.getElementById('founding').scrollIntoView({behavior:PREFS.motion?'smooth':'auto',block:'center'});setTimeout(()=>$('#iname')?.focus({preventScroll:true}),400)};
const originalSettings=modalSettings;
modalSettings=function(m){return originalSettings(m)+`<div class="settings-grid"><label><input type="checkbox" data-pref="motion" ${PREFS.motion?'checked':''}> Cinematic motion</label><label><input type="checkbox" data-pref="effects" ${PREFS.effects?'checked':''}> Spell glow and particles</label><label><input type="checkbox" data-pref="sfx" ${PREFS.sfx?'checked':''}> Combat and interface sounds</label></div><p class="note">Space pauses a battle. 1, 2, and 4 set battle speed. M toggles the original adaptive score. Motion follows your device’s accessibility preference until changed here.</p>`};
document.addEventListener('change',e=>{if(!e.target.dataset.pref)return;PREFS[e.target.dataset.pref]=e.target.checked;document.body.classList.toggle('reduced-motion',!PREFS.motion);try{localStorage.setItem('manitoria-presentation',JSON.stringify(PREFS))}catch{}});
const originalPerkAction=ACT.perk;ACT.perk=d=>{const b=G?.beasts[d.id];if(!b?.offer?.includes(d.k))return;const title=perkName(b,d.k);originalPerkAction(d);toast(`${b.name} learned ${title}.`);if(typeof playCue==='function')playCue('upgrade')};
const originalModal=renderModal;let modalReturnFocus=null;
renderModal=function(){const focused=document.activeElement,wasOpen=!!document.querySelector('.sheet'),hadFocus=focused?.closest?.('.sheet');if(UI.modal&&!wasOpen)modalReturnFocus=document.activeElement;originalModal();const sheet=document.querySelector('.sheet');if(sheet){const title=sheet.querySelector('h2');if(title){title.id='dialog-title';sheet.setAttribute('aria-labelledby','dialog-title')}if(!wasOpen||hadFocus){sheet.setAttribute('tabindex','-1');const candidates=[...sheet.querySelectorAll('button,input,select')],replacement=hadFocus&&candidates.find(el=>!el.disabled&&el.tagName===focused.tagName&&el.textContent===focused.textContent&&JSON.stringify(el.dataset)===JSON.stringify(focused.dataset));(replacement||sheet).focus({preventScroll:true})}}else if(wasOpen&&modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true})};
document.addEventListener('keydown',e=>{if(UI.modal&&e.key==='Tab'){const focusable=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input:not(:disabled),.sheet select:not(:disabled),.sheet textarea')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('sheet'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement.classList.contains('sheet'))){e.preventDefault();first?.focus()}return}if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||UI.modal)return;if(e.key.toLowerCase()==='m'&&G){e.preventDefault();ACT.music()}if(BT&&e.code==='Space'&&!/BUTTON|A/.test(e.target.tagName)){e.preventDefault();ACT.pause()}if(BT&&['1','2','4'].includes(e.key)){e.preventDefault();const next=Number(e.key),el=document.querySelector(`[data-act="speed"][data-s="${next}"]`);if(el)ACT.speed({s:next},el)}});
const originalSave=save;save=function(){try{if(G){if(['result','levelup'].includes(UI.mode)&&UI.result)G.resume={mode:'result',result:UI.result,lvq:UI.lvq||[],lvTotal:UI.lvTotal||0};else if(UI.mode==='season'&&UI.seasonSum)G.resume={mode:'season',seasonSum:UI.seasonSum};else delete G.resume}localStorage.setItem(SAVE_KEY,JSON.stringify(G));return true}catch(e){toast('Browser storage is full. Export your save in Club office to keep your progress.');return false}};
const checkpointLoad=load;load=function(){const g=checkpointLoad(),r=g?.resume;if(r?.mode==='result'&&r.result?.ctx&&Array.isArray(r.result.rows)){UI.mode='result';UI.result=r.result;UI.ctx=r.result.ctx;UI.lvq=(r.lvq||[]).filter(id=>g.beasts[id]&&((g.beasts[id].rolls||0)>0||(g.beasts[id].awaken||[]).length));UI.lvTotal=r.lvTotal||UI.lvq.length}else if(r?.mode==='season'&&r.seasonSum){UI.mode='season';UI.seasonSum=r.seasonSum}return g};

const originalBestiary=viewBestiary;viewBestiary=function(){return originalBestiary().replace('Every species is tuned to win about half its bouts when dropped into an average lineup, so the choice is about fit, not raw power.','Explore their signatures, roles, and weaknesses to find the right fit for your club.')}
const checkpointSeasonContinue=ACT.seasonok;ACT.seasonok=()=>{checkpointSeasonContinue();save()};
